<?php
$page_title='Sessions'; require_once __DIR__.'/../../config/database.php'; require_once __DIR__.'/../../config/session.php'; require_once __DIR__.'/../../config/functions.php'; require_once __DIR__.'/../../config/auth.php'; requireAdmin(); $sessions=$pdo->query("SELECT s.*,u.full_name AS mentor_name,c.title AS course_title,(SELECT COUNT(*) FROM bookings b WHERE b.session_id=s.id) AS booking_count FROM sessions s JOIN users u ON u.id=s.mentor_id LEFT JOIN courses c ON c.id=s.course_id ORDER BY s.scheduled_at DESC")->fetchAll();
?>
<?php include __DIR__.'/../includes/header.php'; ?><div class="admin-shell"><?php include __DIR__.'/../includes/sidebar.php'; ?><main class="admin-main"><div class="admin-topbar"><div><h1 class="admin-title">Session management</h1><p class="admin-subtitle">Monitor schedules, capacity, bookings, and session states.</p></div><a class="btn btn-primary" href="manage.php"><i class="fas fa-plus"></i> Create session</a></div><div class="admin-card admin-table-wrap"><table class="admin-table"><thead><tr><th>Session</th><th>Mentor</th><th>Course</th><th>Scheduled</th><th>Bookings</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($sessions as $session): ?><tr><td><strong><?php echo htmlspecialchars($session['title']); ?></strong><br><small class="text-muted"><?php echo (int)$session['duration']; ?> minutes</small></td><td><?php echo htmlspecialchars($session['mentor_name']); ?></td><td><?php echo htmlspecialchars($session['course_title']??'General'); ?></td><td><?php echo htmlspecialchars(date('M d, Y h:i A',strtotime($session['scheduled_at']))); ?></td><td><?php echo (int)$session['booking_count']; ?>/<?php echo (int)$session['max_participants']; ?></td><td><span class="badge bg-<?php echo $session['status']==='scheduled'?'primary':($session['status']==='completed'?'success':($session['status']==='cancelled'?'danger':'warning')); ?>"><?php echo ucfirst($session['status']); ?></span></td><td><a class="btn btn-sm btn-outline-primary" href="manage.php?id=<?php echo (int)$session['id']; ?>"><i class="fas fa-pen"></i> Manage</a></td></tr><?php endforeach; ?><?php if(!$sessions): ?><tr><td colspan="7" class="text-center text-muted py-4">No sessions found.</td></tr><?php endif; ?></tbody></table></div></main></div><?php include __DIR__.'/../includes/footer.php'; ?>
